// Extraer datos del mensaje de Telegram
const msg = $input.first().json;
const chatId = msg.message?.chat?.id ?? msg.message?.from?.id ?? null;
const text = (msg.message?.text ?? '').trim();
const firstName = msg.message?.from?.first_name ?? '';
const lastName = msg.message?.from?.last_name ?? '';

return [{
  json: {
    chatId,
    text,
    firstName,
    lastName,
    rawMessage: msg
  }
}];

// Combina mensaje entrante con sesión existente
const input = $input.first().json;
const chatId = input.chatId ?? $('Parsear Mensaje').first().json.chatId;
const text = input.text ?? $('Parsear Mensaje').first().json.text;
const firstName = $('Parsear Mensaje').first().json.firstName;

let session = {};
try {
  const raw = input.value ?? input.data ?? null;
  if (raw && typeof raw === 'string') {
    session = JSON.parse(raw);
  } else if (raw && typeof raw === 'object') {
    session = raw;
  }
} catch(e) {
  session = {};
}

// Si no hay state o el usuario envía /start, reiniciar
const state = (text === '/start' || !session.state) ? 'NEW' : session.state;

return [{
  json: {
    chatId,
    text,
    firstName,
    state,
    session
  }
}];

// Estado NEW: Enviar bienvenida y pedir identificación
const chatId = $json.chatId;
const firstName = $json.firstName ?? '';

const reply = `¡Hola${firstName ? ' ' + firstName : ''} 👋!\nSoy tu asistente virtual.\n\nPara poder ayudarte, por favor envíame tu número de *cédula* o *RUC*.`;

return [{
  json: {
    chatId,
    reply,
    next_state: 'AWAIT_ID',
    session: {
      state: 'AWAIT_ID',
      chatId
    }
  }
}];

// Estado AWAIT_ID: Validar cédula/RUC y consultar WS
const chatId = $json.chatId;
const text = $json.text;
const session = $json.session ?? {};

// Limpiar texto (solo dígitos)
const cleaned = text.replace(/\D/g, '');

// Validar formato: 10 dígitos (cédula) o 13 dígitos (RUC)
if (cleaned.length !== 10 && cleaned.length !== 13) {
  return [{
    json: {
      chatId,
      reply: '❌ El número ingresado no parece ser una *cédula* (10 dígitos) ni un *RUC* (13 dígitos).\n\nPor favor, inténtalo de nuevo:',
      next_state: 'AWAIT_ID',
      session: { ...session, state: 'AWAIT_ID' },
      skipWS: true
    }
  }];
}

// Si es válido, pasamos al HTTP Request
return [{
  json: {
    chatId,
    identificacion: cleaned,
    session: { ...session, identificacion: cleaned },
    skipWS: false
  }
}];

// Procesar respuesta del WS: filtrar solo puntos ACTIVOS
const d = $input.first().json;
const chatId = $('Preparar Estado').first().json.chatId;
const session = $('Preparar Estado').first().json.session ?? {};

const puntos = Array.isArray(d.puntos) ? d.puntos : [];

// SOLO ACTIVOS
const activos = puntos.filter(p =>
  String(p?.estado ?? '').trim().toLowerCase() === 'activo'
);

const sessionPatch = {
  ...session,
  identificacion: d.identificacion ?? d.documento ?? session.identificacion,
  nombreCliente: d.nombreCliente ?? null,
  contrato: d.contrato ?? null,
  puntosActivos: activos.map(p => ({
    puntoId: p.puntoId,
    login: p.login,
    nombrePlan: p.nombrePlan,
    ciudad: p.ciudad,
    telefonos: p.telefonos
  }))
};

let next_state = '';
let selectedPuntoId = null;
let selectedLogin = null;
let reply = '';

if (activos.length === 0) {
  next_state = 'HUMAN';
  reply =
    `Hola${d.nombreCliente ? ', ' + d.nombreCliente : ''} 👋\n` +
    `No encuentro un servicio *Activo* asociado a tu identificación.\n` +
    `¿Deseas que te conecte con un asesor? (Responde: *SI* / *NO*)`;
} else if (activos.length === 1) {
  const p = activos[0];
  next_state = 'MAIN_MENU';
  selectedPuntoId = p.puntoId;
  selectedLogin = p.login;
  reply =
    `Hola${d.nombreCliente ? ', ' + d.nombreCliente : ''} 👋\n` +
    `Tu servicio activo:\n` +
    `• ${p.login ?? ''} | ${p.nombrePlan ?? ''} (PuntoId: ${p.puntoId})\n\n` +
    `Elige una opción:\n` +
    `1️⃣ Saldo / fecha de pago\n` +
    `2️⃣ Reenviar factura\n` +
    `3️⃣ Formas de pago / convenios\n` +
    `4️⃣ Plan / servicios contratados\n` +
    `5️⃣ Hablar con un asesor\n` +
    `6️⃣ Cambiar de servicio\n` +
    `0️⃣ Salir`;
} else {
  next_state = 'AWAIT_PUNTO';
  reply =
    `Hola${d.nombreCliente ? ', ' + d.nombreCliente : ''} 👋\n` +
    `Tienes *${activos.length}* servicios activos. Elige cuál deseas consultar:\n\n` +
    activos.map((p, i) =>
      `${i + 1}) ${p.login ?? 'sin_login'} | ${p.nombrePlan ?? 'sin_plan'} | PuntoId ${p.puntoId}`
    ).join('\n');
}

sessionPatch.state = next_state;
sessionPatch.selectedPuntoId = selectedPuntoId;
sessionPatch.selectedLogin = selectedLogin;

return [{
  json: {
    chatId,
    reply,
    next_state,
    selectedPuntoId,
    selectedLogin,
    session: sessionPatch
  }
}];

// Estado AWAIT_PUNTO: usuario selecciona entre puntos activos
const chatId = $json.chatId;
const text = $json.text;
const session = $json.session ?? {};
const activos = Array.isArray(session.puntosActivos) ? session.puntosActivos : [];

const idx = parseInt(text, 10) - 1;

if (!Number.isInteger(idx) || idx < 0 || idx >= activos.length) {
  const reply =
    `Opción inválida. Responde con un número del *1* al *${activos.length}*:\n\n` +
    activos.map((p, i) =>
      `${i + 1}) ${p.login ?? 'sin_login'} | ${p.nombrePlan ?? 'sin_plan'} | PuntoId ${p.puntoId}`
    ).join('\n');

  return [{
    json: {
      chatId,
      reply,
      next_state: 'AWAIT_PUNTO',
      session: { ...session, state: 'AWAIT_PUNTO' }
    }
  }];
}

const chosen = activos[idx];

const reply =
  `✅ Servicio seleccionado:\n` +
  `• ${chosen.login ?? ''} | ${chosen.nombrePlan ?? ''} (PuntoId: ${chosen.puntoId})\n\n` +
  `Elige una opción:\n` +
  `1️⃣ Saldo / fecha de pago\n` +
  `2️⃣ Reenviar factura\n` +
  `3️⃣ Formas de pago / convenios\n` +
  `4️⃣ Plan / servicios contratados\n` +
  `5️⃣ Hablar con un asesor\n` +
  `6️⃣ Cambiar de servicio\n` +
  `0️⃣ Salir`;

return [{
  json: {
    chatId,
    reply,
    next_state: 'MAIN_MENU',
    selectedPuntoId: chosen.puntoId,
    selectedLogin: chosen.login,
    session: {
      ...session,
      state: 'MAIN_MENU',
      selectedPuntoId: chosen.puntoId,
      selectedLogin: chosen.login
    }
  }
}];

// Estado MAIN_MENU: interpretar opción del menú
const chatId = $json.chatId;
const text = $json.text;
const session = $json.session ?? {};
const option = parseInt(text, 10);

const menuText =
  `Elige una opción:\n` +
  `1️⃣ Saldo / fecha de pago\n` +
  `2️⃣ Reenviar factura\n` +
  `3️⃣ Formas de pago / convenios\n` +
  `4️⃣ Plan / servicios contratados\n` +
  `5️⃣ Hablar con un asesor\n` +
  `6️⃣ Cambiar de servicio\n` +
  `0️⃣ Salir`;

if (isNaN(option) || option < 0 || option > 6) {
  return [{
    json: {
      chatId,
      reply: `No entendí tu selección. Por favor responde con un número:\n\n${menuText}`,
      next_state: 'MAIN_MENU',
      menuOption: -1,
      session: { ...session, state: 'MAIN_MENU' }
    }
  }];
}

return [{
  json: {
    chatId,
    text,
    menuOption: option,
    next_state: option === 0 ? 'EXIT' : (option === 5 ? 'HUMAN' : (option === 6 ? 'AWAIT_PUNTO' : 'MAIN_MENU')),
    session
  }
}];

// Opción 1: Consultar saldo y fecha de pago
const chatId = $json.chatId;
const session = $json.session ?? {};

// Aquí deberías llamar a tu WS de saldo. Placeholder:
const reply =
  `💳 *Información de saldo*\n\n` +
  `Servicio: ${session.selectedLogin ?? 'N/A'}\n` +
  `PuntoId: ${session.selectedPuntoId ?? 'N/A'}\n\n` +
  `_(Aquí se mostrará saldo, fecha máxima de pago, etc. desde tu WS)_\n\n` +
  `Elige otra opción o *0* para salir:\n` +
  `1️⃣ Saldo\n2️⃣ Factura\n3️⃣ Formas pago\n4️⃣ Plan\n5️⃣ Asesor\n6️⃣ Cambiar\n0️⃣ Salir`;

return [{
  json: {
    chatId,
    reply,
    next_state: 'MAIN_MENU',
    session: { ...session, state: 'MAIN_MENU' }
  }
}];

// Opción 2: Reenviar factura
const chatId = $json.chatId;
const session = $json.session ?? {};

const reply =
  `🧾 *Reenvío de factura*\n\n` +
  `Servicio: ${session.selectedLogin ?? 'N/A'}\n\n` +
  `_(Aquí se dispara el reenvío de factura por correo o se envía PDF por Telegram)_\n\n` +
  `Elige otra opción o *0* para salir:\n` +
  `1️⃣ Saldo\n2️⃣ Factura\n3️⃣ Formas pago\n4️⃣ Plan\n5️⃣ Asesor\n6️⃣ Cambiar\n0️⃣ Salir`;

return [{
  json: {
    chatId,
    reply,
    next_state: 'MAIN_MENU',
    session: { ...session, state: 'MAIN_MENU' }
  }
}];

// Opción 3: Formas de pago / convenios
const chatId = $json.chatId;
const session = $json.session ?? {};

const reply =
  `🤝 *Formas de pago y convenios*\n\n` +
  `Puedes realizar tus pagos en:\n` +
  `• Transferencia bancaria\n` +
  `• Débito automático\n` +
  `• Puntos de recaudación\n` +
  `• Pago en línea\n\n` +
  `_(Personaliza con tus canales de pago reales)_\n\n` +
  `Elige otra opción o *0* para salir:\n` +
  `1️⃣ Saldo\n2️⃣ Factura\n3️⃣ Formas pago\n4️⃣ Plan\n5️⃣ Asesor\n6️⃣ Cambiar\n0️⃣ Salir`;

return [{
  json: {
    chatId,
    reply,
    next_state: 'MAIN_MENU',
    session: { ...session, state: 'MAIN_MENU' }
  }
}];

// Opción 4: Plan / servicios contratados
const chatId = $json.chatId;
const session = $json.session ?? {};
const activos = session.puntosActivos ?? [];
const selected = activos.find(p => p.puntoId === session.selectedPuntoId);

const reply =
  `📦 *Plan y servicios contratados*\n\n` +
  `Servicio: ${session.selectedLogin ?? 'N/A'}\n` +
  `Plan: ${selected?.nombrePlan ?? 'N/A'}\n` +
  `Ciudad: ${selected?.ciudad ?? 'N/A'}\n\n` +
  `_(Aquí puedes agregar velocidad, productos adicionales, etc. desde tu WS)_\n\n` +
  `Elige otra opción o *0* para salir:\n` +
  `1️⃣ Saldo\n2️⃣ Factura\n3️⃣ Formas pago\n4️⃣ Plan\n5️⃣ Asesor\n6️⃣ Cambiar\n0️⃣ Salir`;

return [{
  json: {
    chatId,
    reply,
    next_state: 'MAIN_MENU',
    session: { ...session, state: 'MAIN_MENU' }
  }
}];

// Opción 5: Hablar con un asesor (handoff humano)
const chatId = $json.chatId;
const session = $json.session ?? {};

const reply =
  `🧑‍💻 *Conexión con asesor*\n\n` +
  `Te voy a conectar con un asesor humano. Por favor espera un momento...\n\n` +
  `_(Aquí se dispara la integración con Chatwoot, CRM, o notificación al equipo de soporte)_`;

return [{
  json: {
    chatId,
    reply,
    next_state: 'HUMAN',
    session: { ...session, state: 'HUMAN' }
  }
}];

// Opción 6: Cambiar de servicio -> vuelve a mostrar puntos activos
const chatId = $json.chatId;
const session = $json.session ?? {};
const activos = session.puntosActivos ?? [];

let reply, next_state;

if (activos.length <= 1) {
  reply = `Solo tienes un servicio activo. No es posible cambiar.\n\n` +
    `Elige una opción:\n` +
    `1️⃣ Saldo\n2️⃣ Factura\n3️⃣ Formas pago\n4️⃣ Plan\n5️⃣ Asesor\n0️⃣ Salir`;
  next_state = 'MAIN_MENU';
} else {
  reply =
    `Tienes *${activos.length}* servicios activos. Elige cuál consultar:\n\n` +
    activos.map((p, i) =>
      `${i + 1}) ${p.login ?? 'sin_login'} | ${p.nombrePlan ?? 'sin_plan'} | PuntoId ${p.puntoId}`
    ).join('\n');
  next_state = 'AWAIT_PUNTO';
}

return [{
  json: {
    chatId,
    reply,
    next_state,
    session: { ...session, state: next_state }
  }
}];

// Opción 0: Salir / limpiar sesión
const chatId = $json.chatId;

const reply = `¡Gracias por usar nuestro servicio! 👋\nSi necesitas algo más, envía /start para comenzar de nuevo.`;

return [{
  json: {
    chatId,
    reply,
    next_state: 'EXIT',
    session: { state: 'NEW', chatId }
  }
}];

// Estado HUMAN: bot en pausa, esperando asesor o respuesta SI/NO
const chatId = $json.chatId;
const text = ($json.text ?? '').trim().toUpperCase();
const session = $json.session ?? {};

if (text === 'NO' || text === '/start') {
  return [{
    json: {
      chatId,
      reply: 'Entendido. Si necesitas algo más, envía /start.',
      next_state: 'NEW',
      session: { state: 'NEW', chatId }
    }
  }];
}

if (text === 'SI' || text === 'SÍ') {
  return [{
    json: {
      chatId,
      reply: '🧑‍💻 Te estamos conectando con un asesor. Por favor espera...',
      next_state: 'HUMAN',
      session: { ...session, state: 'HUMAN' }
    }
  }];
}

// Cualquier otro mensaje en estado HUMAN
return [{
  json: {
    chatId,
    reply: 'Un asesor te atenderá pronto. Si deseas reiniciar, envía /start.',
    next_state: 'HUMAN',
    session: { ...session, state: 'HUMAN' }
  }
}];
